for(const [chapter,entries]of Object.entries(skillsByChapter))for(const [id,title]of entries)SK(id,title);
for(const lesson of oldLessons.values()){
 const parent=lesson.id.split('-l')[0];const n=Number(lesson.id.split('-l')[1])-1;
 const entry=parent==='c15'?['morse-'+(n<8?'characters':n===8?'spacing':n===9?'punctuation':n===10?'words':n===11?'callsigns':n===12?'listening':'qso'),'Morse : '+lesson.title]:skillsByChapter[parent][n];
 SK(...entry);lesson.skillIds=[entry[0]];lesson.referenceIds=oldLinks[lesson.id]||[];
 lesson.certificateWeight=parent==='c15'||lesson.id==='c02-l03'?0:2;lesson.explorationWeight=1;
 lesson.knownCharacters='';lesson.legacyLessonIds=[];lesson.prerequisiteSkillIds=[];
 for(const question of lesson.questions){question.skillIds=[entry[0]];}
}
const newly=[];function add(lesson){newly.push(lesson);return lesson;}
const S={
 app:SK('hamigo-tools','Choisir le bon outil Hamigo'),recall:SK('spaced-recall','Pratiquer le rappel espacé'),numbers:SK('number-basics','Lire décimaux et fractions'),ratio:SK('proportional-reasoning','Raisonner sur un rapport'),formula:SK('formula-reading','Lire une formule'),voltage:SK('dc-voltage','Comprendre une tension'),circuit:SK('closed-circuit','Reconnaître un circuit fermé'),material:SK('resistivity','Résistivité et conductivité'),battery:SK('battery-capacity','Piles et accumulateurs'),meter:SK('measurement-circuits','Brancher les appareils de mesure'),diode:SK('diode-polarity','Polarité d’une diode'),supply:SK('regulated-supply','Redresser, filtrer et réguler'),aop:SK('op-amp-feedback','Amplificateur opérationnel et contre-réaction'),tube:SK('thermionic-tubes','Repères sur les tubes'),rxb:SK('receiver-blocks','Reconnaître les blocs du récepteur'),band:SK('band-allocation','Bandes et statuts des services'),purity:SK('emission-limits','Puissance et rayonnements non essentiels'),cept:SK('cept-travel','Voyager avec le certificat'),rights:SK('installation-rights','Démarches d’installation'),automation:SK('automatic-station','Encadrer une station automatique'),sstv:SK('sstv-principles','Comprendre la SSTV'),sstvRx:SK('sstv-reception','Préparer une réception SSTV'),pota:SK('pota-operation','Découvrir POTA'),sota:SK('sota-operation','Découvrir SOTA'),sdr:SK('sdr-workflow','Utiliser un récepteur SDR'),waterfall:SK('waterfall-reading','Lire un spectre et une cascade'),aprs:SK('aprs-packet','Comprendre les paquets APRS'),ft8:SK('weak-signal-modes','Comprendre un mode à signaux faibles'),portable:SK('portable-power','Préparer l’énergie en portable'),project:SK('experiment-design','Concevoir une expérience radio'),morseWords:SK('morse-words','Reconnaître des groupes Morse'),morseListen:SK('morse-listening','Reconnaître le Morse à l’oreille'),morseEncode:SK('morse-encoding','Produire un message Morse'),morseQso:SK('morse-qso','Comprendre un échange CW'),nato:SK('nato-recall','Retrouver les mots de l’alphabet international')
};
add(L('l-hamigo-bienvenue','Bienvenue dans Hamigo','Tes premiers repères avec Pico',[S.app,S.recall],[
 'Parcours est le fil de tes cours. Ouvre une leçon, lis son introduction et ses fiches Mémo liées, puis essaie les questions. Les cours restent accessibles dans l’ordre que tu choisis : l’ordre proposé aide surtout à rencontrer les bases avant leurs applications.',
 'Les leçons portant le repère Certificat enseignent des connaissances utiles à sa préparation. Les découvertes complètent la pratique radio. Les deux se croisent dans un seul parcours ; les deux barres de Moi suivent les cours réalisés, sans promettre une réussite à l’examen.',
 'Mémo garde les faits, schémas et outils à consulter. Les flashcards demandent de chercher la réponse avant de la révéler. Défis propose les révisions, les mélanges et les examens blancs : revenir sur une notion après un délai aide à la retenir.',
 'Équipe permet d’ajouter tes amis et de comparer votre progression ; Moi rassemble ton activité et tes réglages. Une connexion reste facultative pour apprendre. Pour une question incorrecte, touche son drapeau ; les sources et le contact du projet sont aussi accessibles dans les réglages. Prends le temps de comprendre une correction avant de continuer.'
],[C('Où retrouver rapidement une formule déjà étudiée ?','Dans Mémo',['Dans un commentaire envoyé à un ami','Dans le seul classement XP','En effaçant sa progression'],'Mémo conserve les connaissances et les outils consultables.'),C('Après avoir lu une réponse de flashcard, quelle suite entraîne le rappel ?','La retrouver plus tard sans afficher la réponse',['La laisser toujours visible','Mémoriser sa place dans la liste','Passer toutes les corrections'],'Le rappel après un délai teste la mémoire.'),T('Quel onglet rassemble les examens blancs ?','Défis','Défis propose les entraînements et examens blancs.'),C('Un cours te paraît trop facile. Que peux-tu faire ?','Consulter un autre cours du parcours',['Débloquer obligatoirement tous les précédents','Réinitialiser l’app','Attendre le lendemain'],'Les cours sont libres ; l’ordre conseillé n’est pas un verrou.'),C('Une question contient une erreur. Quel contrôle utiliser ?','Son drapeau de signalement',['Le bouton pour supprimer un ami','La calculatrice','Le volume du téléphone'],'Le signalement garde le contexte et l’identifiant de la question.')],{source:'hamigo',cert:0,explore:0}));
add(L('l-math-decimaux','Des nombres qui parlent','Décimaux, signe et ordre de grandeur',[S.numbers],[
 'Un nombre décimal décrit des unités et des fractions d’unité : 0,5 est la moitié de 1 ; 0,05 en est le vingtième. La virgule française et le point de certaines calculatrices ont le même rôle.',
 'Le signe moins peut représenter une valeur algébrique ou une variation. Passer de 10 à 7 est une variation de −3. Avant de calculer, estime si le résultat attendu est grand, petit, positif ou négatif.',
 'Une fraction est un partage : 3/4 signifie trois parts lorsque l’unité est découpée en quatre. Diviser 3 par 4 donne 0,75. Les parenthèses regroupent ce qu’il faut calculer ensemble.'
],[N('Quelle écriture décimale représente une moitié ?',.5,'','1 ÷ 2 = 0,5.',.0001),N('Quelle valeur décimale vaut 3/4 ?',.75,'','3 ÷ 4 = 0,75.',.0001),N('Un niveau passe de 10 à 7. Quelle variation algébrique ?',-3,'','Valeur finale moins valeur initiale : 7 − 10 = −3.',0),C('Quel nombre est le plus petit ?','0,005',['0,05','0,5','5'],'Chaque déplacement de la virgule change l’ordre de grandeur.')],{refs:['math-basics']}));
add(L('l-math-rapports','Multiplier, partager, comparer','Proportions avant les formules',[S.ratio],[
 'Un rapport compare deux valeurs : 12/3 vaut 4, donc 12 est quatre fois plus grand que 3. La moitié correspond au facteur 0,5, le double au facteur 2.',
 'Deux grandeurs sont proportionnelles lorsque multiplier l’une par un facteur multiplie l’autre par le même facteur. Si trois pièces identiques coûtent six euros, six pièces coûtent douze euros.',
 'La proportion inverse suit l’effet contraire : à quantité totale fixe, deux fois plus de parts donnent des parts deux fois plus petites. Chercher ce sens de variation évite d’appliquer une règle à l’envers.'
],[N('Quel est le rapport 20/5 ?',4,'','20 est quatre fois 5.',0),N('Trois longueurs identiques totalisent 6 m. Quelle longueur pour six éléments ?',12,'m','Le nombre double, la longueur totale double.'),C('Une quantité fixe est partagée entre deux fois plus de personnes. Chaque part…','Est divisée par deux',['Double','Reste identique','Est multipliée par quatre'],'C’est un partage inverse.'),N('La moitié de 0,8 vaut combien ?',.4,'','0,8 × 0,5 = 0,4.',.0001)],{refs:['math-basics']}));
add(L('l-math-formules','Lire les lettres d’une formule','Une relation, puis des valeurs',[S.formula],[
 'Une formule décrit une relation entre grandeurs. Dans distance = vitesse × durée, les mots peuvent être abrégés d, v et t. Le signe × indique une multiplication ; deux lettres voisines peuvent aussi désigner un produit.',
 'Commence par nommer ce qui est connu et ce qui est demandé. Avec une vitesse de 3 mètres par seconde pendant 4 secondes, la distance est 3 × 4 = 12 mètres. L’unité raconte le calcul : les secondes se simplifient.',
 'Pour isoler un facteur, divise les deux côtés par l’autre facteur. Si d = v × t, alors t = d/v. On vérifie ensuite si le résultat répond à la grandeur cherchée, avec la bonne unité.'
],[N('À 3 m/s pendant 4 s, quelle distance ?',12,'m','d = v × t = 3 × 4 = 12 m.'),C('Pour d = v × t, comment isoler t ?','t = d/v',['t = d × v','t = v/d','t = d + v'],'Divise les deux membres par v.'),T('Le résultat d’un calcul de durée doit être exprimé dans une unité de…',['temps','durée'],'La seconde est une unité de temps.'),N('Une distance de 20 m est parcourue à 5 m/s. Quelle durée ?',4,'s','t = d/v = 20/5 = 4 s.')],{refs:['math-basics']}));
add(L('l-circuit-ferme','Une boucle pour le courant','Source, trajet et interruption',[S.circuit],[
 'Un circuit simple contient une source d’énergie, des conducteurs et un récepteur. Une pile fournit une tension entre ses bornes. Une lampe ou une résistance reçoit de l’énergie lorsque le circuit permet un courant.',
 'Il faut un trajet fermé entre les deux bornes de la source pour entretenir un courant continu dans cette boucle. Ouvrir un interrupteur coupe ce trajet. Une tension peut pourtant rester présente aux bornes de la pile.',
 'Relier directement les bornes d’une pile avec un fil crée un court-circuit : le courant peut devenir dangereux. Pour les exercices réels, utilise une maquette basse tension et une alimentation limitée en courant.'
],[C('Dans une boucle simple, que fait un interrupteur ouvert ?','Il interrompt le trajet du courant',['Il augmente toujours le courant','Il inverse la pile','Il transforme la résistance en antenne'],'Le trajet est coupé.'),T('Comment appelle-t-on le contact presque sans résistance entre les bornes de la pile ?',['court-circuit','court circuit'],'Le court-circuit peut provoquer une forte intensité.'),C('Une pile déconnectée de toute charge peut-elle garder une tension ?','Oui',['Non, jamais','Uniquement en alternatif','Uniquement avec un ampèremètre'],'La tension peut exister sans courant.'),C('Pour débuter sur une maquette, quelle alimentation convient ?','Une basse tension limitée en courant',['Une prise secteur ouverte','Un circuit haute tension inconnu','Une batterie court-circuitée'],'Limiter tension et courant réduit les risques de la maquette.')],{source:'dc',refs:['dc-circuits','station-safety']}));
add(L('l-tension-deux-points','La tension entre deux points','Un écart de potentiel, en volts',[S.voltage],[
 'La tension est une différence de potentiel électrique entre deux points. Elle s’exprime en volts, symbole V. On peut la comparer à une différence de niveau qui rend un transfert d’énergie possible ; cette image ne décrit pas tous les détails du circuit.',
 'Une pile de 9 V présente environ neuf volts entre ses bornes à vide. La valeur précise dépend de son état et de la charge. Une borne n’a pas une tension absolue : il faut toujours un autre point de référence.',
 'Le voltmètre se branche entre les deux points à comparer, donc en parallèle. Inverser ses pointes change le signe affiché en courant continu. Un appareil réel doit être réglé sur une fonction et un calibre adaptés.'
],[T('Quelle est l’unité de tension ?',['volt','V'],'La tension s’exprime en volts.'),C('Une mesure de tension concerne…','Deux points du circuit',['La couleur d’un fil','Un courant sans référence','Seulement la borne positive'],'Une tension est une différence de potentiel.'),C('Comment branche-t-on un voltmètre ?','En parallèle',['En série comme un fil','En court-circuitant la source','Uniquement hors tension'],'Il compare le potentiel de ses deux bornes.'),N('Un voltmètre continu affiche +9 V. On inverse ses deux pointes : quelle valeur idéale ?',-9,'V','Le choix de référence est inversé.')],{source:'dc',refs:['dc-circuits','measurements']}));
add(L('l-energie-duree','Des watts aux wattheures','Puissance instantanée, énergie accumulée',[SK('energy-duration','Relier énergie et durée')],[
 'La puissance est le rythme d’un transfert d’énergie. Un appareil de 10 W consomme dix joules par seconde. L’énergie décrit le total transféré pendant une durée.',
 'À puissance constante, E = P × t. Avec P en watts et t en heures, l’énergie est en wattheures. Un appareil de 10 W utilisé deux heures demande 20 Wh. Un wattheure vaut 3 600 joules.',
 'Comparer une batterie et une consommation exige des unités cohérentes. Un ampèreheure ne suffit pas à décrire une énergie sans connaître la tension ; les pertes et la capacité réellement utilisable réduisent l’autonomie.'
],[N('Un appareil de 5 W fonctionne 3 h. Quelle énergie ?',15,'Wh','E = P × t = 5 × 3.'),N('Combien de joules vaut 1 Wh ?',3600,'J','Une heure contient 3 600 secondes.',0),C('La puissance mesure…','Un transfert d’énergie par unité de temps',['Une énergie sans durée','Seulement une tension','Le nombre de cellules'],'Le watt est un joule par seconde.'),N('Un appareil consomme 12 Wh en 2 h à puissance constante. Puissance moyenne ?',6,'W','P = E/t = 12/2.')],{source:'ohm',refs:['dc-circuits','units'],prerequisites:['electric-power']}));
add(L('l-fils-materiaux','Pourquoi les fils résistent','Longueur, section et matériau',[S.material],[
 'Un conducteur réel possède une résistance. Pour un fil homogène, elle augmente avec sa longueur et diminue lorsque sa section augmente. La résistivité caractérise le matériau dans des conditions données.',
 'La relation R = ρ × L/S utilise la longueur L, la section S et la résistivité ρ, avec des unités compatibles. Doubler la longueur double la résistance ; doubler la section la divise par deux.',
 'La section est une aire, pas un diamètre. Pour une section ronde, doubler le diamètre multiplie l’aire par quatre. La température modifie aussi la résistance ; pour les métaux usuels, elle tend à augmenter quand le fil chauffe.'
],[C('Pour un même matériau et la même section, doubler la longueur…','Double R',['Divise R par deux','Ne change jamais R','Divise R par quatre'],'R est proportionnelle à L.'),C('Pour un fil rond, doubler le diamètre multiplie la section par…','4',['2','0,5','8'],'L’aire dépend du carré du diamètre.'),T('Quelle propriété caractérise l’opposition d’un matériau au courant ?',['résistivité','resistivite'],'La résistivité intervient dans R = ρL/S.'),N('Un fil vaut 2 Ω. Même longueur et matériau, section doublée : nouvelle résistance ?',1,'Ω','R est inversement proportionnelle à S.')],{source:'dc',refs:['dc-circuits','materials','math-basics']}));
add(L('l-voltemetre-amperemetre','Mesurer sans changer la boucle','Voltmètre en parallèle, ampèremètre en série',[S.meter],[
 'Pour mesurer un courant, l’ampèremètre doit être traversé par ce courant : il se place en série après ouverture de la branche hors tension. Pour une tension, le voltmètre se place en parallèle entre deux points.',
 'Un ampèremètre a une faible résistance interne ; le placer directement sur une source peut créer un court-circuit. Un voltmètre a une résistance d’entrée élevée pour prélever peu de courant. Les appareils réels ont des limites.',
 'Avant de brancher, vérifie les cordons, la borne utilisée, la fonction et le calibre. Une mesure de résistance se fait sur un circuit hors tension et déchargé. La maquette affichée ici reste un exercice basse tension.'
],[q('circuit','Place les appareils dans les deux emplacements de mesure.','Le courant traverse l’ampèremètre ; le voltmètre compare les deux points.',{visual:'circuit:measurement',pairs:[{left:'courant',right:'Ampèremètre'},{left:'tension',right:'Voltmètre'}],choices:['Ampèremètre','Voltmètre','Interrupteur','Résistance']}),C('Quel branchement peut court-circuiter une source ?','Un ampèremètre directement en parallèle',['Un voltmètre adapté en parallèle','Une résistance limitée en série','Un interrupteur ouvert'],'L’ampèremètre a une très faible résistance.'),T('Pour mesurer une résistance, le circuit doit être…',['hors tension','débranché','coupe'],'L’ohmmètre applique sa propre excitation ; une source externe fausse et peut endommager la mesure.'),C('Pourquoi souhaite-t-on une forte résistance d’entrée du voltmètre ?','Pour prélever peu de courant',['Pour créer un court-circuit','Pour augmenter la puissance disponible','Pour supprimer la tension mesurée'],'Une faible charge perturbe moins le circuit.')],{source:'dc',refs:['measurements'],prerequisites:['dc-voltage','dc-current']}));
add(L('l-pile-resistance-interne','La pile sous charge','Une source réelle n’est pas idéale',[S.battery],[
 'Une pile réelle possède une tension à vide et une résistance interne. Quand elle débite, une partie de sa tension se perd dans cette résistance. La tension disponible aux bornes diminue donc sous charge.',
 'Le modèle simple est une source idéale E en série avec une résistance r. Si le courant vaut I, la tension de sortie est U = E − rI. C’est un modèle d’apprentissage, pas une description de toute la chimie.',
 'La capacité en Ah mesure une quantité de charge dans des conditions précises. Une recharge doit correspondre à la chimie et aux protections prévues. Une pile non rechargeable ne doit pas être chargée comme un accumulateur.'
],[N('E = 12 V, r = 1 Ω et I = 2 A. Tension aux bornes ?',10,'V','U = E − rI = 12 − 2.'),C('Une pile réelle sous forte charge peut présenter…','Une tension plus basse qu’à vide',['Une tension nécessairement infinie','Aucune perte interne','Un courant nul par définition'],'Le courant entraîne une chute dans la résistance interne.'),T('Une capacité en Ah mesure une quantité de…',['charge','charge électrique'],'1 Ah correspond à 3 600 coulombs.'),C('Quel chargeur choisir pour un accumulateur ?','Celui adapté à sa chimie et ses limites',['Tout chargeur de même couleur','Un fil direct au secteur','Une tension arbitrairement élevée'],'La chimie impose la méthode et les limites de charge.')],{source:'dc',refs:['transformers-batteries']}));
add(L('l-rms-sans-confusion','Crête ou efficace ?','Comparer l’effet thermique',[SK('rms-sine','Valeur efficace d’une sinusoïde')],[
 'La valeur de crête est l’extrême atteint par un signal. La valeur crête à crête est l’écart entre minimum et maximum. Une sinusoïde centrée a deux crêtes opposées.',
 'La valeur efficace indique la valeur continue produisant la même puissance moyenne dans une résistance. Pour une sinusoïde pure centrée, Ueff = Umax/√2. Cette relation ne s’applique pas automatiquement à toute forme de signal.',
 'Un oscilloscope et un multimètre peuvent afficher des grandeurs différentes. Lis le réglage et l’unité avant de comparer. Une composante continue ou un signal déformé exige un raisonnement adapté.'
],[N('Une sinusoïde centrée atteint +10 V et −10 V. Valeur crête à crête ?',20,'V','Ucc = Umax − Umin = 10 − (−10).'),N('Une sinusoïde a 14,142 V de crête. Valeur efficace approximative ?',10,'V','Ueff = Umax/√2.',.02),C('La formule Ueff = Umax/√2 concerne ici…','Une sinusoïde pure centrée',['Tout signal sans condition','La capacité d’une pile','Un signal carré de même crête'],'La forme d’onde fait partie des hypothèses.'),T('La valeur efficace compare quel effet dans une résistance ?',['thermique','chauffage','échauffement'],'Elle compare la puissance moyenne dissipée.')],{source:'ac',refs:['ac-circuits','measurements']}));
add(L('l-condensateur-polarite','Choisir un condensateur','Capacité, tension et polarité',[SK('capacitor-ratings','Respecter les limites d’un condensateur')],[
 'La capacité décrit la charge stockée par volt : Q = C × U. Elle s’exprime en farads. En pratique, on emploie souvent microfarads, nanofarads et picofarads.',
 'Un condensateur a une tension maximale admissible. Certains modèles sont polarisés : leurs bornes positive et négative doivent être respectées. Une capacité correcte ne suffit pas à rendre un composant interchangeable.',
 'Même déconnecté, un condensateur peut garder de l’énergie. Sur une maquette basse tension, prépare une décharge contrôlée appropriée ; sur une alimentation dangereuse, il faut une procédure et des compétences adaptées.'
],[N('C = 10 µF sous 5 V. Charge stockée ?',50,'µC','Q = C × U ; les microfarads donnent ici des microcoulombs.'),C('Quel remplacement respecte ces deux critères : 10 µF, tension de service 16 V, circuit à 9 V ?','10 µF, 25 V, polarité adaptée',['10 µF, 6,3 V','1 000 µF, 1 V','10 nF, 25 V sans autre vérification'],'La capacité et la tenue en tension conviennent ; la technologie et la polarité restent à vérifier.'),T('Quelle unité mesure une capacité ?',['farad','F'],'Le farad est le coulomb par volt.'),C('Après débranchement, une capacité est-elle nécessairement sans tension ?','Non',['Oui, immédiatement','Oui si elle est grande','Oui si elle est bleue'],'La charge peut subsister.')],{source:'ac',refs:['ac-circuits','station-safety']}));
add(L('l-bobine-coupure','Couper un courant dans une bobine','Comprendre la surtension inductive',[SK('inductor-switching','Anticiper une surtension inductive')],[
 'Une bobine s’oppose aux variations du courant. Son inductance s’exprime en henrys. Elle stocke de l’énergie dans un champ magnétique lorsque le courant la traverse.',
 'À la coupure, le courant ne peut pas changer instantanément dans le modèle idéal. Une tension importante peut apparaître aux bornes de l’interrupteur. C’est une raison de protéger la commande d’un relais.',
 'Une diode de roue libre placée dans le bon sens aux bornes d’une bobine alimentée en continu fournit un chemin après coupure. Elle est bloquée pendant l’alimentation normale. Ce montage n’est pas une protection universelle pour l’alternatif ou toutes les vitesses de commutation.'
],[T('Quelle grandeur d’une bobine s’exprime en henrys ?',['inductance'],'Le henry est l’unité d’inductance.'),C('À la coupure d’un relais continu, quel phénomène faut-il prévoir ?','Une surtension inductive',['Une disparition instantanée de toute énergie','Un changement d’indicatif','Une capacité nécessairement nulle'],'La bobine s’oppose à la variation brusque de courant.'),C('Pendant l’alimentation normale, la diode de roue libre doit être…','Bloquée',['En court-circuit direct de la source','Absente par définition','Remplacée par un fil'],'Elle conduit au moment où la bobine restitue son énergie.'),C('La diode de roue libre convient-elle telle quelle à toute bobine alternative ?','Non, le montage doit être adapté',['Oui, toujours','Oui si le fil est vert','Oui sans connaître la tension'],'Le courant alternatif et la dynamique imposent d’autres contraintes.')],{source:'ac',refs:['ac-circuits','measurements']}));
add(L('l-filtre-coupure','Où commence l’atténuation ?','Lire une fréquence de coupure',[SK('filter-cutoff','Interpréter une coupure et une pente')],[
 'Un filtre transmet certaines fréquences mieux que d’autres. Un passe-bas conserve les basses fréquences ; un passe-haut conserve les hautes. La transition est progressive.',
 'Pour un simple RC du premier ordre, la fréquence de coupure vaut 1/(2πRC). Au point de coupure, la puissance est moitié de la référence, soit environ −3 dB, sous les hypothèses de charge du modèle.',
 'Une octave double la fréquence ; une décade la multiplie par dix. Loin de la coupure, un premier ordre tend vers une pente de 6 dB par octave, soit 20 dB par décade. Ce sont des pentes asymptotiques.'
],[T('Quel filtre privilégie les fréquences les plus basses ?',['passe-bas','passe bas'],'Un passe-bas atténue davantage les hautes fréquences.'),N('De 1 kHz à 2 kHz, combien d’octaves ?',1,'octave','Une octave est un doublement.',0),N('À −3 dB, la puissance transmise vaut approximativement quelle fraction de la référence ?',.5,'','−3 dB correspond approximativement à la moitié.',.01),C('La transition d’un filtre réel est…','Progressive',['Toujours un mur vertical','Sans effet sur la phase','Indépendante des composants'],'La réponse varie continûment avec la fréquence.')],{source:'filters',refs:['filters','decibels']}));
add(L('l-decibels-reperes','Des rapports faciles à retrouver','Deux, dix, gains et pertes',[SK('decibel-landmarks','Reconnaître les rapports usuels en dB')],[
 'Le décibel exprime un rapport. Pour des puissances, multiplier par dix donne +10 dB ; diviser par dix donne −10 dB. Doubler donne environ +3 dB et diviser par deux environ −3 dB.',
 'Des rapports successifs se multiplient, mais leurs valeurs en dB s’additionnent. Un amplificateur de +10 dB suivi d’un câble à −3 dB donne environ +7 dB pour la chaîne.',
 'Un dBm est une puissance rapportée à 1 mW, pas un simple rapport sans référence. Pour les tensions, le facteur 20 ne convient que si les impédances de comparaison sont identiques.'
],[N('Une puissance est divisée par dix. Variation en dB ?',-10,'dB','10 log10(0,1) = −10.',0),N('Un gain de 10 dB puis une perte de 3 dB donnent…',7,'dB','On additionne +10 et −3.',0),T('Quelle puissance de référence définit le dBm ?',['1 mW','un milliwatt','1 milliwatt'],'0 dBm correspond à 1 mW.'),C('Doubler une puissance donne environ…','+3 dB',['+6 dB','+20 dB','−3 dB'],'10 log10(2) ≈ 3,01 dB.')],{source:'filters',refs:['decibels']}));
add(L('l-diode-sens','Une diode a un sens','Anode, cathode et polarisation',[S.diode],[
 'Une diode ordinaire possède une anode et une cathode. En polarisation directe, l’anode est à un potentiel supérieur à celui de la cathode et le courant peut circuler. En inverse, le courant reste faible tant que les limites ne sont pas dépassées.',
 'La tension directe n’est pas un seuil parfait universel. Elle dépend de la technologie, du courant et de la température. En exercice, une diode au silicium est souvent modélisée avec environ 0,6 à 0,7 V.',
 'Une DEL émet de la lumière lorsqu’elle est correctement polarisée. Une résistance en série limite son courant. La valeur se calcule à partir de la tension restante et du courant voulu ; brancher une DEL seule sur une source peut la détruire.'
],[T('Comment s’appelle la borne opposée à l’anode ?',['cathode'],'La diode possède anode et cathode.'),C('Quel élément limite simplement le courant d’une DEL sur une source continue ?','Une résistance en série',['Un fil en parallèle sur la source','Une antenne seule','Un voltmètre en série'],'La résistance absorbe une partie de la tension et fixe le courant.'),N('Source 5 V, DEL 2 V, courant 10 mA. Résistance série idéale ?',300,'Ω','R = (5 − 2)/0,010 = 300 Ω.'),q('circuit','Complète la maquette basse tension de la DEL.','La pile fournit la tension ; la résistance limite le courant ; la DEL est le témoin lumineux.',{visual:'circuit:series',pairs:[{left:'source',right:'Pile'},{left:'protection',right:'Résistance'},{left:'témoin',right:'DEL'}],choices:['Pile','Résistance','DEL','Ampèremètre','Bobine']})],{source:'active',refs:['diodes-power','dc-circuits'],prerequisites:['ohm-law']}));
add(L('l-alimentation-etages','Du redressement à la régulation','Le rôle de chaque étage',[S.supply],[
 'Une alimentation classique peut associer transformateur, redresseur, condensateur de filtrage et régulateur. Le transformateur adapte une tension alternative et peut assurer un isolement selon sa construction.',
 'Le redresseur fait circuler le courant dans un seul sens à la sortie. Le condensateur se recharge près des crêtes puis alimente la charge entre elles : la tension conserve une ondulation résiduelle.',
 'Le régulateur réduit les variations dans ses limites de courant, tension et température. Il ne rend pas une alimentation secteur sûre à manipuler. Les montages de ce parcours se raisonnent sur schéma ou sur maquette basse tension.'
],[T('Quel étage transforme l’alternatif en tension unidirectionnelle ?',['redresseur','pont de diodes'],'Le redressement sélectionne ou retourne les alternances.'),C('Le condensateur de filtrage sert surtout à…','Réduire l’ondulation entre les crêtes',['Attribuer un indicatif','Créer l’isolement secteur à lui seul','Garantir une tension nulle après arrêt'],'Il restitue de l’énergie entre les recharges.'),C('Une charge plus forte sur un condensateur identique tend à…','Augmenter l’ondulation',['Supprimer toujours l’ondulation','Changer la fréquence secteur','Annuler tout courant'],'La décharge entre les crêtes est plus importante.'),T('Quel étage stabilise la tension dans ses limites ?',['régulateur','regulateur'],'Le régulateur compense certaines variations de tension et charge.')],{source:'active',refs:['diodes-power','transformers-batteries']}));
add(L('l-aop-entrees','Deux entrées, une comparaison','Amplificateur opérationnel idéal',[S.aop],[
 'Un amplificateur opérationnel possède deux entrées, repérées plus et moins, et une sortie. Sans contre-réaction, un très faible écart entre entrées peut conduire la sortie vers une limite d’alimentation : c’est le gain en boucle ouverte élevé.',
 'Avec une contre-réaction négative adaptée et sans saturation, le montage agit pour rendre les tensions d’entrée presque égales. Dans le modèle idéal, les courants d’entrée sont nuls. Ces hypothèses ne signifient pas que les deux bornes sont reliées par un fil.',
 'L’alimentation, la plage des entrées, la vitesse et l’amplitude de sortie bornent le fonctionnement réel. Une relation linéaire ne s’applique plus si la sortie sature.'
],[T('Comment appelle-t-on le renvoi d’une partie de la sortie qui réduit l’écart d’entrée ?',['contre-réaction négative','contre reaction negative'],'La boucle négative stabilise le fonctionnement linéaire.'),C('Dans le modèle idéal d’AOP, les courants d’entrée valent…','Zéro',['Toujours 1 A','Le courant de sortie entier','Une valeur infinie'],'L’impédance d’entrée idéale est infinie.'),C('Si la sortie atteint sa limite d’alimentation, le montage est…','Saturé',['Parfaitement linéaire sans condition','En circuit ouvert nécessairement','Un transformateur'],'La relation linéaire peut ne plus être valable.'),C('Des tensions presque égales aux entrées prouvent-elles une liaison par fil ?','Non',['Oui','Oui si le gain est grand','Oui si la sortie est positive'],'La boucle peut imposer cet état sans liaison directe.')],{source:'aop',refs:['logic-digital'],prerequisites:['transistor-bias']}));
add(L('l-aop-montages','Inverseur, suiveur, non-inverseur','Reconnaître la fonction du montage',[S.aop],[
 'Dans le montage inverseur idéal avec contre-réaction et fonctionnement linéaire, le gain vaut −R2/R1. Le signe moins indique une inversion du signal par rapport à la référence.',
 'Le non-inverseur idéal a un gain 1 + R2/R1. Le suiveur relie la sortie à l’entrée moins ; le signal arrive à l’entrée plus et le gain vaut environ un. Il permet de transmettre une tension en prélevant peu de courant en entrée.',
 'Les valeurs des résistances ne permettent pas d’ignorer les limites de sortie et d’alimentation. Calcule le gain, puis vérifie si l’amplitude demandée reste possible.'
],[N('Inverseur : R1 = 10 kΩ et R2 = 20 kΩ. Gain idéal ?',-2,'','−R2/R1 = −2.'),N('Non-inverseur : R1 = 10 kΩ, R2 = 20 kΩ. Gain idéal ?',3,'','1 + R2/R1 = 3.'),T('Quel montage a un gain voisin de un et une forte impédance d’entrée ?',['suiveur','suiveur de tension'],'Le suiveur reproduit la tension dans ses limites.'),C('Le signe moins du gain inverseur traduit…','L’inversion du signal',['Une puissance nécessairement négative','Un circuit sans alimentation','Une résistance négative obligatoire'],'Il décrit la polarité du signal de sortie.')],{source:'aop',refs:['logic-digital'],prerequisites:['op-amp-feedback']}));
add(L('l-tubes-reperes','Reconnaître les tubes','Cathode, grille et anode',[S.tube],[
 'Dans un tube thermoïonique, une cathode chauffée émet des électrons. Une anode positive peut les attirer. Une diode à vide possède ces deux électrodes principales, en plus du chauffage.',
 'Une triode ajoute une grille de commande qui contrôle le courant d’anode. Tétrodes et pentodes ajoutent d’autres grilles. Ces repères servent à reconnaître la fonction et les symboles ; construire un appareil à tubes n’est pas une première manipulation.',
 'Les appareils à tubes peuvent utiliser de hautes tensions et des condensateurs chargés après arrêt. Le schéma ne dispense jamais d’une procédure de sécurité ni d’une compétence réelle.'
],[T('Quelle électrode chauffée émet les électrons ?',['cathode'],'L’émission thermoïonique vient de la cathode chauffée.'),T('Quelle électrode contrôle le courant d’une triode ?',['grille','grille de commande'],'La triode ajoute une grille de commande.'),C('Une diode à vide possède principalement…','Cathode et anode',['Base, émetteur et collecteur','Grille, source et drain','Deux antennes'],'Le chauffage permet l’émission électronique.'),C('Un appareil à tubes éteint est-il automatiquement sûr à ouvrir ?','Non',['Oui, immédiatement','Oui si l’écran est noir','Oui sans mesurer'],'L’énergie et les hautes tensions peuvent subsister.')],{source:'active',refs:['transistors-tubes','station-safety']}));
add(L('l-radio-ondes','Une onde transporte une variation','Fréquence, bande et message',[SK('radio-wave-basics','Relier onde, fréquence et bande')],[
 'Un signal radio est une variation de champs électromagnétiques qui se propage. Pour apprendre, distingue le signal physique et le message porté : une voix peut modifier certaines caractéristiques d’une onde porteuse.',
 'La fréquence compte les répétitions par seconde : un hertz signifie un cycle par seconde. Un mégahertz vaut un million de hertz. Une bande est un intervalle de fréquences, pas un canal unique.',
 'Émettre met un signal dans un espace partagé. La fréquence, la largeur occupée et le mode doivent être compatibles avec les autorisations du lieu. L’écoute seule ne donne pas une autorisation de transmettre.'
],[T('Quelle unité compte les cycles par seconde ?',['hertz','Hz'],'Un hertz est un cycle par seconde.'),N('Combien de hertz font 2 MHz ?',2000000,'Hz','Méga multiplie par un million.',0),C('Une bande radio est…','Un intervalle de fréquences',['Un mot de passe','Toujours un canal unique','Un indicatif attribué'],'Une bande rassemble une plage de fréquences.'),C('Pour ajouter une voix à une porteuse, on utilise…','Une modulation',['Une suppression de toute onde','Une migration de sauvegarde','Un changement de prénom'],'La modulation porte le message dans les variations du signal.')],{source:'radio',refs:['propagation','modulations']}));
add(L('l-band-plans','Autorisation et plan de bande','Deux informations complémentaires',[S.band],[
 'Une attribution nationale fixe les bandes et leurs conditions d’utilisation. Un plan de bande recommande une organisation des modes entre amateurs. Une recommandation ne peut pas élargir une autorisation légale.',
 'Toute la largeur d’une émission doit rester dans la bande autorisée. Une porteuse placée juste sur une limite ne garantit donc pas que ses bandes latérales restent dedans.',
 'Dans un partage secondaire, l’amateur doit protéger les services primaires et ne peut pas réclamer leur protection contre les brouillages. Les conditions dépendent de la bande et du territoire ; consulte les textes et les fiches datées.'
],[C('Un plan de bande autorise-t-il à dépasser une limite nationale ?','Non',['Oui si la fréquence est calme','Oui en numérique','Oui à faible puissance'],'Une recommandation ne crée pas un droit d’émettre.'),T('Quel statut impose de protéger les services primaires ?',['secondaire','service secondaire'],'Un service secondaire ne doit pas causer de brouillage préjudiciable au primaire.'),C('Que doit-on garder à l’intérieur des limites autorisées ?','Toute la largeur de l’émission',['Seulement l’affichage central','Seulement le microphone','Seulement l’indicatif'],'Les bandes latérales font aussi partie du signal.'),C('Avant d’émettre à l’étranger, quelle règle s’applique ?','Celle du territoire et de la bande utilisés',['Toujours la même que chez soi','Le seul classement Hamigo','Le choix automatique du poste'],'Le territoire d’exploitation impose ses conditions.')],{source:'rules',refs:['bands','itu-regions']}));
add(L('l-identification-carnet','Une émission identifiable','Indicatif et trace du contact',[SK('identification-log','Identifier et consigner un contact')],[
 'En France, l’indicatif est transmis au début et à la fin d’une période d’émission ; au-delà de quinze minutes sur une même fréquence, il doit aussi revenir au moins toutes les quinze minutes. Une nouvelle fréquence demande une nouvelle identification au début de la période.',
 'Le journal garde date, heure, indicatifs de l’utilisateur et des correspondants, fréquence, classe d’émission et lieu d’émission. Un outil numérique convient s’il conserve les renseignements et permet leur présentation.',
 'Le journal doit être conservé au moins un an après la dernière inscription. Le prénom ou le modèle du poste ne remplacent jamais l’indicatif. Les groupes proposés en entraînement ne sont pas attribués par Hamigo.'
],[N('Pendant une émission dépassant quinze minutes, délai maximal entre identifications ?',15,'min','L’article 4 fixe au moins toutes les quinze minutes.',0),C('Quel événement impose une identification au début de la nouvelle période ?','Un changement de fréquence',['Un changement de fond d’écran','Une nouvelle semaine Hamigo','L’ouverture de la calculatrice'],'L’indicatif doit être donné sur la nouvelle fréquence.'),N('Durée minimale de conservation après la dernière inscription du journal ?',1,'an','L’article 6 demande au moins un an.',0),T('Quel identifiant annoncer, plutôt que le seul prénom ?',['indicatif','indicatif d’appel'],'L’indicatif identifie la station dans les émissions.')],{source:'rules',refs:['operating-rules','callsigns']}));
add(L('l-emission-puissances','Puissance utile et émissions indésirables','Lire une limite sans confondre les références',[S.purity],[
 'La puissance de sortie décrit ce que fournit l’émetteur. Les pertes de ligne réduisent ce qui arrive à l’antenne ; le gain d’antenne modifie le rayonnement selon les directions. PAR et PIRE emploient des références différentes.',
 'Une limite peut être exprimée en puissance de crête, PAR ou PIRE. Il faut lire exactement la condition de la bande et du territoire. L’application donne des repères, mais une ancienne annexe ne remplace pas les décisions qui l’ont modifiée.',
 'Le signal utile doit aussi rester propre : harmoniques, produits parasites et largeur excessive peuvent brouiller. Une augmentation de puissance ne répare pas une modulation écrêtée. Les essais commencent sur une charge adaptée avec des mesures pertinentes.'
],[T('Quelle référence d’antenne définit la PIRE ?',['isotrope','antenne isotrope'],'La PIRE prend comme référence une antenne isotrope.'),C('La seule puissance affichée au poste suffit-elle à calculer la PIRE ?','Non, il faut aussi pertes et gain',['Oui, toujours','Oui si le poste est neuf','Oui en FM uniquement'],'La ligne et l’antenne interviennent.'),C('Que peut provoquer un gain micro excessif ?','Un élargissement et de la distorsion',['Une conformité garantie','La disparition du bruit partout','Une baisse automatique du ROS'],'L’écrêtage crée des composantes indésirables.'),T('Comment appelle-t-on les multiples entiers de la fréquence fondamentale ?',['harmoniques'],'Les harmoniques sont des multiples entiers de la fondamentale.')],{source:'rules',refs:['transmitter-limits','antennas','emc-noise']}));
add(L('l-cept-voyage','Le certificat dans la valise','Reconnaissance et règles du pays hôte',[S.cept],[
 'Un certificat et un indicatif français ne donnent pas les mêmes droits partout. Les accords de reconnaissance, dont la recommandation CEPT T/R 61-01 lorsqu’elle est applicable, facilitent certains séjours.',
 'Avant le voyage, vérifie le pays participant, la durée, les documents, le préfixe à employer et les conditions nationales. Une bande ouverte en France peut être différente dans le pays visité.',
 'La reconnaissance d’un certificat de compétence et l’autorisation d’exploiter sont liées mais distinctes. Pour un cas concret, l’administration du pays hôte et les textes actuels sont la référence.'
],[C('Quelle réglementation de bandes suivre en voyage ?','Celle du pays hôte',['Celle du dernier QSO','Toujours celle de France','Le plan personnel du poste'],'L’exploitation a lieu sur le territoire du pays hôte.'),T('Quel organisme publie la recommandation T/R 61-01 ?',['CEPT'],'La CEPT publie ces recommandations de reconnaissance.'),C('Que vérifier avant de choisir le préfixe en voyage ?','Les conditions applicables au séjour et au pays',['La couleur du passeport uniquement','Les XP de son ami','Le dernier indicatif aléatoire de l’app'],'Les modalités peuvent varier.'),C('Une ancienne liste de pays suffit-elle pour un voyage réel ?','Non, vérifier son état actuel',['Oui pour toujours','Oui si le séjour est court','Oui avec une antenne portable'],'La participation et les modalités doivent être actualisées.')],{source:'rules',refs:['callsigns','operating-rules']}));
add(L('l-installation-droits','Installer sans supposer','Déclaration, terrain et autorisations',[S.rights],[
 'Installer une station peut concerner plusieurs règles : utilisation radio, déclaration, droit d’antenne, urbanisme, bail ou copropriété, sécurité et accès au terrain. Une seule démarche ne remplace pas toutes les autres.',
 'Le repère de déclaration radio pour une installation amateur de PAR supérieure à 5 W ne doit pas être confondu avec une autorisation d’urbanisme. Les fiches Mémo renvoient aux sources et distinguent les valeurs de l’édition ancienne des textes actuels.',
 'Pour un mât ou un site réel, vérifie les exigences locales avant les travaux. L’autorisation d’accéder à un lieu n’autorise pas nécessairement à y fixer une antenne. Une installation temporaire demande aussi le respect des règles du site.'
],[C('Une déclaration radio remplace-t-elle toutes les règles d’urbanisme ?','Non',['Oui','Oui si le mât est portable','Oui avec le certificat'],'Les démarches portent sur des objets différents.'),C('Pour une installation sur un site protégé, quelle action est utile ?','Vérifier les règles locales avant les travaux',['Installer puis demander après','S’appuyer uniquement sur une ancienne question','Augmenter la puissance'],'Les contraintes dépendent du site.'),T('Quel organisme français reçoit les déclarations radio évoquées ici ?',['ANFR'],'La fiche donne le lien ANFR et le cadre applicable.'),C('L’accès autorisé à un terrain implique-t-il le droit d’y fixer tout équipement ?','Non',['Oui, sans limite','Oui à partir de dix contacts','Oui avec un indicatif court'],'Les droits d’installation doivent aussi être vérifiés.')],{source:'rules',refs:['station-safety','operating-rules']}));
add(L('l-signal-dbm','Une puissance avec sa référence','Relier dBm, milliwatts et watts',[SK('dbm-reference','Puissances en dBm')],[
 'Le dBm exprime une puissance par rapport à 1 mW. Zéro dBm signifie donc 1 mW ; ajouter 10 dB multiplie cette puissance par dix.',
 'Ainsi 10 dBm valent 10 mW, 20 dBm valent 100 mW et 30 dBm valent 1 000 mW, soit 1 W. Un niveau négatif est une puissance positive inférieure à 1 mW.',
 'Pour comparer deux niveaux en dBm, soustrais-les : de −100 à −90 dBm, le niveau augmente de 10 dB. Ne confonds pas cette différence avec une puissance de 10 dBm.'
],[N('Quelle puissance vaut 0 dBm ?',1,'mW','Le dBm est référencé à 1 mW.',0),N('Quelle puissance vaut 30 dBm ?',1,'W','1 mW × 1 000 = 1 W.'),N('De −100 à −90 dBm, quelle variation ?',10,'dB','−90 − (−100) = +10 dB.',0),C('Une puissance de −20 dBm est…','Positive et inférieure à 1 mW',['Une puissance négative impossible','Toujours 20 W','Nulle par définition'],'Le signe décrit le rapport à la référence, pas une énergie négative.')],{source:'radio',refs:['decibels','radio-blocks']}));
add(L('l-recepteur-etapes','Que fait chaque bloc ?','De l’antenne au son',[S.rxb],[
 'Une antenne capte de nombreux signaux. Un filtre aide à retenir une zone du spectre. Le récepteur sélectionne ensuite le signal voulu, en évitant autant que possible la surcharge des étages.',
 'La démodulation extrait le message porté par la variation de l’onde. Un étage audio adapte ensuite le niveau pour le haut-parleur. Chaque bloc a une fonction : amplifier ne remplace pas sélectionner ou démoduler.',
 'Ce synoptique simplifié montre des fonctions, pas un schéma à câbler. Les récepteurs réels peuvent employer une conversion de fréquence, du traitement numérique ou plusieurs étages pour une même fonction.'
],[q('circuit','Complète ce synoptique simplifié de réception.','Antenne : capter ; filtre : sélectionner ; démodulateur : extraire le message ; haut-parleur : restituer le son.',{visual:'circuit:receiver',pairs:[{left:'capter',right:'Antenne'},{left:'sélectionner',right:'Filtre'},{left:'extraire',right:'Démodulateur'},{left:'écouter',right:'Haut-parleur'}],choices:['Antenne','Filtre','Démodulateur','Haut-parleur','Fusible','Pile']}),T('Quelle opération extrait le message de la porteuse ?',['démodulation','demodulation'],'La démodulation récupère l’information modulante.'),C('Un amplificateur peut-il remplacer à lui seul un filtre sélectif ?','Non',['Oui toujours','Oui si le volume est fort','Oui sans alimenter le circuit'],'Gain et sélection sont deux fonctions.'),C('Ce dessin de blocs est-il un câblage électrique complet ?','Non, il décrit les fonctions',['Oui, il suffit de relier n’importe quels fils','Oui sans composants','Oui sans alimentation'],'Un synoptique ne contient pas tous les détails électriques.')],{source:'radio',refs:['radio-blocks']}));
add(L('l-sdr-premiers','Une radio pilotée par logiciel','Antenne, échantillons et démodulation',[S.sdr],[
 'Un récepteur SDR effectue une partie du traitement du signal par logiciel. L’antenne et les étages analogiques restent nécessaires ; le programme travaille ensuite sur des échantillons.',
 'Un récepteur seul permet d’explorer les signaux sans émettre. Un appareil possédant aussi une émission doit être configuré et utilisé dans le cadre autorisé. La présence d’un bouton logiciel ne donne pas un droit d’usage.',
 'Pour un premier essai, choisis un signal public approprié, une antenne adaptée, la fréquence et le bon mode. Réduis le gain si des signaux fantômes apparaissent sur une grande partie du spectre : le récepteur peut être surchargé.'
],[T('Que représente le S de SDR ?',['software','logiciel'],'Software Defined Radio désigne une radio définie en partie par logiciel.'),C('Un récepteur SDR a-t-il encore besoin d’une antenne adaptée ?','Oui',['Non, le logiciel remplace tout','Uniquement pour enregistrer','Uniquement avec Internet'],'Les étages physiques captent et conditionnent le signal.'),C('Des signaux fantômes se multiplient en montant le gain. Que tester ?','Diminuer le gain et comparer',['Toujours pousser le gain à fond','Émettre sans indicatif','Changer seulement la couleur du graphe'],'Une surcharge peut créer des produits indésirables.'),C('Un SDR uniquement récepteur peut-il transmettre par un simple changement de logiciel ?','Non',['Oui dans tous les cas','Oui en activant le micro','Oui en changeant le prénom'],'Il manque la chaîne physique d’émission.')],{source:'sdr',cert:0,explore:3,refs:['radio-blocks','digital-signals']}));
add(L('l-cascade-spectre','Lire un spectre qui défile','Fréquence, intensité et temps',[S.waterfall],[
 'Un spectre représente le niveau selon la fréquence à un instant ou sur une moyenne. Une cascade ajoute le temps : chaque nouvelle ligne représente une nouvelle mesure et les couleurs codent le niveau.',
 'Une trace étroite persistante peut correspondre à une porteuse stable. Un signal vocal modulé occupe une largeur qui évolue. La couleur seule ne donne pas un report fiable : l’échelle, le gain et les réglages comptent.',
 'Pour comparer deux essais, conserve les mêmes réglages et note fréquence, mode, largeur et gain. Observer une trace ne suffit pas à identifier son service ; vérifie le contexte avant de conclure.'
],[T('Quel axe supplémentaire apporte une cascade par rapport au spectre instantané ?',['temps','le temps'],'La cascade empile des mesures successives.'),C('Changer le gain du récepteur peut-il modifier les couleurs affichées ?','Oui',['Non, jamais','Seulement si l’antenne disparaît','Seulement en Morse'],'Les couleurs dépendent aussi de l’échelle et du gain.'),C('Une ligne étroite persistante permet-elle d’identifier à elle seule le service ?','Non',['Oui toujours','Oui si elle est rouge','Oui avec un grand écran'],'Plusieurs signaux peuvent se ressembler.'),T('Quelle grandeur horizontale porte habituellement le spectre d’un récepteur ?',['fréquence','frequence'],'Le spectre répartit les niveaux selon la fréquence.')],{source:'sdr',cert:0,explore:3,refs:['radio-blocks','modulations']}));
add(L('l-portable-energie','Préparer l’autonomie','Une station légère et mesurée',[S.portable],[
 'Une sortie radio commence par un objectif, une durée et un bilan d’énergie. La consommation en réception et en émission diffère ; le temps passé dans chaque état compte.',
 'Pour un calcul idéal, une batterie de 12 V et 5 Ah représente environ 60 Wh. L’énergie utilisable est plus faible selon la chimie, le courant, la température, les pertes et la limite de décharge.',
 'Prévois une protection près de la source, des connexions adaptées et une marge d’autonomie. Vérifie la météo, l’accès et les personnes autour de l’antenne. Ces exercices ne remplacent pas les notices du matériel.'
],[N('Énergie idéale d’une batterie de 12 V, 5 Ah ?',60,'Wh','E ≈ U × capacité = 12 × 5.'),N('Station idéale consommant 10 W avec 40 Wh utilisables : autonomie ?',4,'h','t = E/P = 40/10.'),C('Pourquoi garder une marge sur l’autonomie théorique ?','Les conditions et les pertes réduisent l’énergie utilisable',['Parce que les Ah sont des volts','Parce que le gain d’antenne recharge toujours la pile','Parce que le journal fournit du courant'],'Le modèle idéal omet plusieurs effets réels.'),C('Où prévoir la protection contre un court-circuit du câble de batterie ?','Près de la source, selon le montage',['Uniquement sur l’antenne','Dans le carnet','Après tout le câble sans autre protection'],'La protection doit limiter l’énergie dans le câblage exposé.')],{source:'dc',cert:0,explore:3,refs:['transformers-batteries','station-safety']}));
add(L('l-dipole-projet','Préparer un dipôle','Dimensions de départ et réglage',[SK('dipole-project','Planifier et mesurer un dipôle')],[
 'Un dipôle demi-onde possède deux brins de part et d’autre du point d’alimentation. La demi-longueur d’onde théorique dans le vide donne un ordre de grandeur, pas une dimension finale universelle.',
 'Pour 14 MHz, la longueur d’onde vaut environ 300/14, soit 21,4 m ; sa moitié environ 10,7 m. Le matériau, les extrémités et l’environnement modifient la longueur physique nécessaire à la résonance.',
 'Prépare des points d’attache sûrs, loin des lignes électriques, puis mesure à faible puissance ou avec un analyseur adapté. Ajuste progressivement et note les résultats. Un ROS faible ne prouve pas à lui seul un bon rayonnement.'
],[N('Longueur d’onde approximative à 14 MHz ?',300/14,'m','λ ≈ 300/f en MHz.',.1),N('Une longueur d’onde vaut 20 m. Demi-longueur ?',10,'m','Une demi-onde est la moitié de λ.'),C('La demi-onde dans le vide est-elle une longueur de coupe finale garantie ?','Non',['Oui pour tous les fils','Oui quelle que soit la hauteur','Oui même contre un mur'],'L’environnement et les effets d’extrémité comptent.'),C('Un faible ROS garantit-il une antenne qui rayonne efficacement ?','Non',['Oui toujours','Oui si le câble est long','Oui sans mesurer les pertes'],'Une charge fictive peut elle aussi être bien adaptée.')],{source:'antennas',cert:0,explore:3,refs:['antennas','transmission-lines','station-safety']}));
add(L('l-antenne-mesures','Comparer avant de couper','Une variable à la fois',[SK('antenna-experiment','Interpréter un essai d’antenne')],[
 'Une mesure devient utile quand ses conditions sont connues. Note la fréquence, la disposition de l’antenne, la ligne, l’appareil et ses réglages avant de modifier une longueur.',
 'Comparer le même montage avant et après une petite modification aide à relier cause et effet. Changer simultanément le câble, la hauteur et les brins rend l’interprétation difficile.',
 'Un analyseur permet d’observer une évolution avec la fréquence. Cherche une tendance cohérente ; ne confonds pas le minimum de ROS avec une preuve de portée ou de sécurité.'
],[C('Pour comprendre l’effet d’un raccourcissement, que garder constant ?','Autant que possible les autres conditions',['Aucun réglage','Un nombre d’XP fixe','Le prénom du correspondant'],'Une variable à la fois rend la comparaison interprétable.'),T('Quel document simple garde les réglages et résultats d’un essai ?',['carnet','carnet de mesures','notes','journal de mesures'],'Des notes datées permettent de comparer.'),C('La meilleure valeur ponctuelle suffit-elle à expliquer toute l’antenne ?','Non',['Oui','Oui si elle vaut un','Oui avec une nouvelle pile'],'La fréquence, les pertes et le rayonnement restent à considérer.'),C('Avant une mesure près d’un mât, quelle priorité ?','La sécurité mécanique et électrique',['La couleur de la courbe','Le score SRS','La vitesse de partage'],'Les mesures ne dispensent pas d’un site sûr.')],{source:'antennas',cert:0,explore:3,refs:['antennas','measurements']}));
add(L('l-pota-decouverte','Une radio depuis un parc','Activer ou contacter une activation',[S.pota],[
 'POTA invite à établir des contacts depuis des parcs référencés. L’activateur se trouve dans le parc ; le chasseur le contacte depuis un lieu autorisé. Le programme ne remplace ni la réglementation radio ni les règles d’accès.',
 'Une activation réussie demande actuellement au moins dix contacts admissibles dans une même journée UTC. Les limites officielles du parc et son ouverture doivent être vérifiées. Être juste à côté du parc ne suffit pas.',
 'Le journal de l’activateur permet de créditer les contacts. Prépare l’installation et l’écoute du canal avant tout appel ; une sortie reste utile même si le nombre de contacts est insuffisant.'
],[T('Dans POTA, comment appelle-t-on la station située dans le parc ?',['activateur','activatrice'],'L’activateur opère depuis le parc référencé.'),N('Minimum actuel de contacts admissibles pour réussir une activation POTA ?',10,'QSO','Le règlement demande dix contacts dans une même journée UTC.',0),C('Une référence POTA garantit-elle le droit d’entrer partout dans le parc ?','Non',['Oui','Oui avec dix QSO','Oui en semaine uniquement'],'Les accès et restrictions locales restent applicables.'),C('Quel repère de temps utilise le total journalier POTA ?','UTC',['L’heure du téléphone sans vérification','La journée Hamigo commençant à 03 h','Le fuseau du correspondant'],'Le programme compte la journée UTC.')],{source:'pota',cert:0,explore:3,refs:['operating-rules','station-safety']}));
add(L('l-pota-contacts','Un contact POTA valide','Échange direct et journal',[S.pota],[
 'Les correspondants doivent se recevoir assez clairement pour noter leurs indicatifs. Le règlement POTA ne demande pas un échange verbal unique imposé à tous ; donne les informations utiles et reste bref si d’autres stations attendent.',
 'Les contacts via relais terrestre et les contacts entièrement automatiques ne sont pas admissibles dans POTA. Chaque opérateur doit agir directement dans le contact. Ces règles sportives sont distinctes du droit radio national.',
 'Conserve un journal exact. Une référence de parc entendue sur Internet ne remplace pas la réception de l’indicatif du correspondant dans le QSO.'
],[C('Un QSO entièrement automatique est-il admissible en POTA ?','Non',['Oui toujours','Oui si le logiciel le propose','Oui avec une grande batterie'],'Le règlement exige une action directe des deux opérateurs.'),C('Un contact via relais terrestre est-il admissible pour cette activation ?','Non',['Oui toujours','Oui si le parc est loin','Oui après dix autres contacts'],'Le règlement POTA exclut les relais terrestres.'),T('Quelle identité faut-il recevoir pour noter le correspondant ?',['indicatif','indicatif d’appel'],'Le contact doit permettre l’identification correcte.'),C('Un programme sportif peut-il autoriser une bande interdite localement ?','Non',['Oui','Oui à faible puissance','Oui le week-end'],'Les règles légales priment sur celles du programme.')],{source:'pota',cert:0,explore:3,refs:['operating-rules']}));
add(L('l-sota-sommets','La radio depuis un sommet','Un projet radio et une sortie préparée',[S.sota],[
 'SOTA associe contacts radio et sommets référencés. Un activateur opère dans la zone d’activation ; un chasseur peut le contacter depuis ailleurs. La zone est définie par l’altitude et les règles de l’association, pas par un cercle horizontal arbitraire.',
 'Le repère général est une position au plus 25 mètres plus bas que le sommet en altitude. Cela ne donne pas accès à une propriété fermée. Consulte les règles générales et le manuel de l’association avant un projet concret.',
 'Météo, autonomie, itinéraire et heure de retour passent avant le nombre de contacts. Un sommet référencé ne garantit ni une approche simple ni une permission d’installation.'
],[N('Repère général : écart vertical maximal sous le sommet dans la zone d’activation ?',25,'m','La FAQ SOTA indique 25 mètres verticaux.',0),C('La zone d’activation est-elle un rayon de 25 m sur la carte ?','Non',['Oui','Oui si le terrain est plat','Oui dans tous les pays'],'Le repère concerne l’altitude.'),C('Une référence SOTA autorise-t-elle à traverser une propriété interdite ?','Non',['Oui avec un indicatif','Oui après inscription','Oui pour un contact court'],'Les droits d’accès restent indépendants.'),C('La météo se dégrade. Quelle décision est prioritaire ?','Replier si la sécurité le demande',['Finir les contacts à tout prix','Monter la puissance sans limite','Ignorer l’heure de retour'],'Le projet radio reste subordonné à la sécurité.')],{source:'sota',cert:0,explore:3,refs:['station-safety','operating-rules']}));
add(L('l-iss-passage','Préparer un passage de l’ISS','Trajectoire, mode actif et horizon',[SK('iss-pass','Préparer une écoute de l’ISS')],[
 'L’ISS passe au-dessus de l’horizon pendant une fenêtre limitée. Une prédiction de passage utilise la position de la station au sol et des éléments orbitaux à jour. L’élévation indique la hauteur apparente au-dessus de l’horizon.',
 'La présence géométrique de l’ISS ne garantit pas une émission radio. ARISS publie l’état des équipements et les activités prévues ; les modes et fréquences peuvent changer ou être interrompus.',
 'Prépare une écoute avec un horizon dégagé, le bon mode et les fréquences annoncées. Le Doppler fait varier la fréquence reçue au cours du passage. Écouter un contact scolaire ne donne pas une invitation à émettre dessus.'
],[T('Quelle organisation publie ici l’état radio de l’ISS ?',['ARISS'],'ARISS fournit l’état des stations et les annonces.'),C('Un passage visible garantit-il une transmission SSTV ?','Non',['Oui à chaque orbite','Oui la nuit seulement','Oui si l’antenne est longue'],'Les activités dépendent de l’état et de la programmation.'),C('Quel paramètre décrit la hauteur apparente au-dessus de l’horizon ?','L’élévation',['Le ROS','Le gain micro','Le report T'],'L’élévation est un angle de visée.'),C('Pourquoi préparer une correction de fréquence ?','À cause du Doppler',['Pour choisir un prénom','Pour attribuer un indicatif','Pour supprimer toute atmosphère'],'Le mouvement relatif décale la fréquence reçue.')],{source:'iss',cert:0,explore:3,refs:['propagation','antennas']}));
add(L('l-satellite-monte-descente','Deux trajets pour un relais spatial','Montée, descente et écoute de soi',[SK('satellite-links','Distinguer montée et descente satellite')],[
 'La liaison montante va du sol au satellite ; la descendante revient du satellite au sol. Elles peuvent employer des bandes et des modes différents. Il faut suivre la fiche du satellite actif, sans généraliser depuis l’ISS.',
 'Un transpondeur ou un relais spatial partage une ressource limitée entre les stations. Prépare la réception avant de transmettre et emploie une puissance adaptée. Une forte puissance n’allonge pas la durée du passage.',
 'La trajectoire, les pertes de polarisation et le Doppler évoluent. Comprendre ces changements aide à distinguer une perte de réception d’un mauvais réglage ou d’une fin de visibilité.'
],[T('Quel trajet va de la station au sol vers le satellite ?',['montée','liaison montante','uplink'],'La montée va vers le satellite.'),T('Quel trajet revient du satellite au sol ?',['descente','liaison descendante','downlink'],'La descente est le signal reçu au sol.'),C('Faut-il supposer la même fréquence pour montée et descente ?','Non',['Oui toujours','Oui en portable','Oui après le certificat'],'La fiche du satellite précise les deux trajets.'),C('Qu’est-ce qu’une forte puissance ne change pas ?','La durée de visibilité géométrique',['Le niveau reçu dans toutes les conditions','La consommation de la batterie','Le risque de surcharge'],'L’orbite fixe la fenêtre de passage.')],{source:'iss',cert:0,explore:3,refs:['propagation','radio-blocks']}));
add(L('l-sstv-image-son','Une image dans un signal audio','La télévision à balayage lent',[S.sstv],[
 'La SSTV transmet une image fixe sous forme de variations audio. Un logiciel traduit progressivement ces variations en lignes et couleurs. Ce n’est pas une vidéo fluide ni un fichier envoyé instantanément.',
 'Le mode SSTV définit la manière de coder l’image et sa durée. Émetteur et décodeur doivent employer des paramètres compatibles. Une image partielle peut simplement provenir d’une réception commencée en cours de transmission.',
 'Les activités SSTV de l’ISS sont annoncées ponctuellement par ARISS. Hamigo propose une compréhension du trajet et des erreurs possibles ; il ne promet pas une émission à chaque passage.'
],[T('La SSTV transmet principalement quel type de contenu ?',['image fixe','images fixes','image'],'La télévision à balayage lent reconstruit une image fixe.'),C('Le son reçu et le décodeur doivent partager…','Un mode compatible',['Un même prénom','Le même nombre d’XP','Une même batterie'],'Le mode définit la structure temporelle du signal.'),C('Une réception commence au milieu de l’émission. Résultat possible ?','Une image partielle',['Une image complète garantie','Un QSO automatiquement validé','Une absence de toute information'],'Les lignes précédentes n’ont pas été reçues.'),C('Le SSTV de l’ISS est-il permanent à chaque passage ?','Non',['Oui toujours','Oui sur chaque fréquence','Oui si le ciel est clair'],'Il s’agit d’activités ponctuelles annoncées.')],{source:'sstv',cert:0,explore:3,refs:['modulations','digital-signals']}));
add(L('l-sstv-reception','Recevoir une image pas à pas','Une chaîne audio correctement réglée',[S.sstvRx],[
 'La chaîne commence par une antenne, un récepteur réglé sur l’activité, puis un trajet audio vers un décodeur SSTV. Le trajet peut être acoustique ou câblé selon le matériel. Aucune émission n’est nécessaire pour cet essai de réception.',
 'Évite l’écrêtage : un niveau audio plus fort ne rend pas toujours l’image meilleure. Conserve l’enregistrement pour comparer les décodages et distinguer un signal manquant d’un mauvais réglage.',
 'Prépare le mode annoncé et commence l’enregistrement avant la trame. Le bruit, un mauvais mode, un manque de signal ou une erreur de rythme peuvent dégrader l’image. Modifie une seule variable à la fois.'
],[C('Dans cette chaîne, à quoi sert le décodeur SSTV ?','À reconstruire l’image depuis l’audio',['À attribuer un certificat','À augmenter l’orbite','À remplacer l’antenne'],'Le décodeur interprète les variations du signal audio.'),C('Une entrée audio saturée doit conduire à…','Réduire le niveau et comparer',['Monter encore le volume','Émettre sans autorisation','Changer le carnet uniquement'],'L’écrêtage détruit de l’information.'),T('Quelle trace garder pour tester plusieurs décodages du même passage ?',['enregistrement audio','audio','enregistrement'],'Une même capture permet une comparaison reproductible.'),C('Faut-il transmettre pour recevoir cette image ?','Non',['Oui dans tous les cas','Oui avant chaque ligne','Oui pour synchroniser une pile'],'Cette activité est une réception.')],{source:'sstv',cert:0,explore:3,refs:['radio-blocks','measurements']}));
add(L('l-aprs-paquets','Des positions, mais aussi des messages','Comprendre le rôle des paquets APRS',[S.aprs],[
 'APRS échange des informations locales sous forme de paquets : positions, états, messages et objets. Une carte peut afficher ces données, mais APRS ne se réduit pas au suivi de véhicules.',
 'Un relais numérique peut répéter un paquet ; une passerelle peut l’acheminer vers un réseau Internet. Voir une station sur un site web ne prouve donc pas que tu la reçois directement à la radio.',
 'Avant toute émission, vérifie fréquence, identification, contenu, intervalle et règles applicables. Une cadence excessive occupe inutilement le canal. L’application n’envoie aucun paquet réel dans les exercices.'
],[T('Comment appelle-t-on les unités d’information échangées ici ?',['paquets','paquet'],'APRS emploie des paquets structurés.'),C('Une station visible sur une carte web est-elle forcément reçue directement par ton antenne ?','Non',['Oui','Oui si la carte est récente','Oui si son icône est verte'],'La donnée peut avoir transité par une passerelle Internet.'),C('APRS transporte-t-il uniquement des positions ?','Non, aussi messages et états',['Oui uniquement des coordonnées','Oui uniquement des vidéos','Oui uniquement des certificats'],'Le protocole sert aussi à partager des informations locales.'),C('Pourquoi éviter une cadence excessive de balises ?','Pour limiter l’occupation et les collisions',['Pour modifier le code Morse','Pour augmenter le gain de l’antenne','Pour supprimer l’indicatif'],'Le canal est partagé.')],{source:'aprs',cert:0,explore:3,refs:['digital-signals','operating-rules']}));
add(L('l-numerique-faibles-signaux','Décoder n’est pas converser','Messages courts et signaux faibles',[S.ft8],[
 'Des modes comme FT8 utilisent un codage structuré pour échanger de courts messages dans des conditions de signal difficiles. Ils n’ont pas le même objectif qu’une conversation audio libre.',
 'Le logiciel aide au décodage, mais l’opérateur doit vérifier les paramètres, le contenu et la conformité de la station. L’horloge, la fréquence et le niveau audio sont des éléments de la chaîne.',
 'Un signal décodé ne garantit pas une liaison dans les deux sens. Le journal doit refléter les échanges réellement accomplis. Une séquence assistée par logiciel ne constitue pas une autorisation générale de laisser émettre sans contrôle.'
],[C('FT8 est surtout conçu ici pour…','De courts messages structurés',['La vidéo haute définition','Une téléphonie sans limites','Une identité secrète garantie'],'Les messages structurés servent des liaisons à signaux faibles.'),C('Décoder une station prouve-t-il qu’elle t’a reçu ?','Non',['Oui','Oui avec 100 W','Oui avec une horloge correcte'],'La liaison inverse reste à établir.'),T('Quel paramètre de temps faut-il soigner dans ces modes synchronisés ?',['horloge','synchronisation de l’horloge','heure'],'Les séquences doivent être alignées temporellement.'),C('Le logiciel dispense-t-il de vérifier la conformité du contenu et de l’émission ?','Non',['Oui','Oui en automatique','Oui quand le mode est populaire'],'L’opérateur reste responsable.')],{source:'digital',cert:0,explore:3,refs:['digital-signals','modulations']}));
add(L('l-automatisme-controle','Automatiser avec un arrêt réel','La règle française ne se résume pas à un minuteur',[S.automation],[
 'Une station automatique peut émettre sans intervention à chaque message. En France, l’article 5 de la décision ARCEP 2012-1241 exige un dispositif permettant de faire cesser immédiatement ses émissions par télécommande.',
 'Cette exigence ne constitue pas une autorisation générale pour tout programme et tout contenu, vingt-quatre heures sur vingt-quatre. Bandes, identification, puissance, absence de brouillage et objet amateur restent applicables.',
 'Avant un projet, vérifie le protocole, les démarches et les règles propres au service et au site. Prévois un arrêt qui fonctionne réellement en cas de défaut. Un simple bouton dans une page web ne prouve pas que la chaîne d’arrêt atteint l’émetteur.'
],[T('Quel moyen d’arrêt exige l’article 5 pour une station automatique ?',['télécommande','telecommande','arrêt par télécommande'],'Les émissions doivent pouvoir cesser immédiatement par télécommande.'),C('Cette obligation autorise-t-elle tous les bots radio sans autre condition ?','Non',['Oui','Oui si le programme est libre','Oui après minuit'],'Les autres conditions légales continuent de s’appliquer.'),C('Que faut-il tester dans un dispositif d’arrêt ?','La cessation effective des émissions',['Seulement la couleur du bouton','Uniquement la page d’accueil','Le nombre de connexions GitHub'],'Il faut contrôler le résultat dans la chaîne réelle.'),C('Un brouillage préjudiciable est observé. Quelle priorité ?','Faire cesser les émissions concernées',['Continuer jusqu’au prochain jour','Masquer le journal','Changer seulement l’indicatif'],'Le dispositif doit permettre une cessation immédiate.')],{source:'rules',cert:0,explore:3,refs:['operating-rules','emc-noise']}));
add(L('l-projet-experience','Imaginer une expérience utile','Une hypothèse, une mesure, une conclusion',[S.project],[
 'Une expérience commence par une question précise : par exemple, cette position d’antenne améliore-t-elle la réception d’un signal stable ? Choisis un indicateur observable et des conditions comparables.',
 'Garde une configuration de référence, puis change une seule variable. Note les résultats, les unités et les limites. Une observation isolée peut venir de la propagation ou du bruit plutôt que de la modification.',
 'Commence par la réception ou une maquette basse tension. Pour une émission réelle, le certificat, l’indicatif et les règles restent nécessaires. Une conclusion utile indique ce que l’essai montre et ce qu’il ne permet pas de décider.'
],[C('Une amélioration ponctuelle après déplacement prouve-t-elle que la position est toujours meilleure ?','Non',['Oui','Oui si le signal est fort','Oui sans autre mesure'],'Les conditions peuvent varier indépendamment.'),T('Comment appelle-t-on la configuration conservée pour comparer ?',['référence','configuration de référence','temoin','témoin'],'La référence permet la comparaison.'),C('Pourquoi noter les unités avec les résultats ?','Pour savoir quelle grandeur est mesurée',['Pour augmenter les XP','Pour empêcher le bruit','Pour changer le gain'],'Un nombre seul est ambigu.'),C('Quelle conclusion est la plus rigoureuse ?','Décrire l’effet observé et ses conditions',['Promettre le même résultat partout','Ignorer les essais défavorables','Confondre adaptation et portée'],'La conclusion doit rester dans le périmètre de l’essai.')],{source:'radio',cert:0,explore:3,refs:['measurements','station-safety']}));
const nato={A:'Alfa',B:'Bravo',C:'Charlie',D:'Delta',E:'Echo',F:'Foxtrot',G:'Golf',H:'Hotel',I:'India',J:'Juliett',K:'Kilo',L:'Lima',M:'Mike',N:'November',O:'Oscar',P:'Papa',Q:'Quebec',R:'Romeo',S:'Sierra',T:'Tango',U:'Uniform',V:'Victor',W:'Whiskey',X:'X-ray',Y:'Yankee',Z:'Zulu'};
const natoGroups=[['l-nato-premiers','Les premiers mots pour épeler','ABCDEF','ABCDEF'],['l-nato-milieu','Des lettres qui se ressemblent','GHIJKLMNOP','ABCDEFGHIJKLMNOP'],['l-nato-fin','Finir l’alphabet international','QRSTUVWXYZ','ABCDEFGHIJKLMNOPQRSTUVWXYZ']];
for(const [id,title,letters,known]of natoGroups){
 const questions=[...letters].map((letter,i)=>(i%3===1?P:T)(`Quel mot de l’alphabet international représente ${letter} ?`,letter==='X'?['X-ray','X ray','Xray']:[nato[letter]],`${letter} s’épelle ${nato[letter]}.`));
 add(L(id,title,'Retrouver le mot sans le voir dans une liste',[S.nato],[
  'L’alphabet international remplace chaque lettre par un mot conventionnel pour l’identifier dans le bruit. Les mots ne sont pas choisis librement : la lettre conserve son mot quelle que soit la langue de la conversation.',
  [...letters].map(letter=>`${letter} : ${nato[letter]}`).join(' ; ')+'. Lis ces mots, écoute-les dans la fiche Mémo puis essaie de les retrouver sans regarder.',
  'Épelle de petits groupes dans un ordre varié. Si un mot manque, relis ce repère puis reviens-y plus tard. Les graphies officielles Alfa et Juliett évitent d’apprendre une autre orthographe. La réponse vocale est facultative : le clavier reste disponible.'
 ],questions,{source:'nato',refs:['nato'],known,cert:1}));
}
add(L('l-nato-groupes','Épeler un groupe nouveau','Garder les mots et l’ordre des lettres',[S.nato],[
 'Quand tu connais les mots, entraîne l’enchaînement : lis chaque caractère dans l’ordre, puis retrouve son mot sans une banque déjà triée. Les chiffres restent prononcés distinctement.',
 'F4MNO est ici un groupe d’entraînement : Foxtrot, quatre, Mike, November, Oscar. Hamigo n’attribue aucun indicatif et un exemple ressemblant à un indicatif réel ne t’autorise pas à l’utiliser sur l’air.',
 'Le groupe change entre les séances. Prends le temps de vérifier les lettres entendues plutôt que leur position dans une liste. Une saisie au clavier ou une réponse vocale entraînent le même rappel.'
],[{...P('Épelle le groupe d’entraînement F4MNO avec l’alphabet international.',['Foxtrot quatre Mike November Oscar','Foxtrot 4 Mike November Oscar'],'Lis les caractères dans leur ordre : F, 4, M, N, O.'),template:{type:'nato-call',sourceText:'Épelle le groupe d’entraînement {{call}} avec l’alphabet international.',characters:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',fallback:'F4MNO',mode:'nato'}},T('Quel mot représente W ?','Whiskey','W s’épelle Whiskey.'),P('Épelle le groupe VHF.','Victor Hotel Foxtrot','Les mots correspondent à V, H puis F.'),T('Quel mot représente la lettre J ?','Juliett','La graphie officielle contient deux t.')],{source:'nato',refs:['nato','callsigns'],known:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',prerequisites:[S.nato]}));
const learnedGroups=[
 ['l-morse-mots-etim','Quatre lettres, déjà des mots','ETIM',['ETE','MIMI','TETE'],'Ces groupes n’utilisent que E, T, I et M. Même avec quatre caractères, tu peux alterner des rythmes et garder les pauses entre lettres. Les accents ne sont pas codés dans ces groupes d’entraînement.'],
 ['l-morse-mots-anso','Des mots avec A, N, S et O','ETIMANSO',['SIMON','MAISON','SON'],'Ajoute A, N, S et O aux caractères déjà appris. Les nouveaux mots obligent à retrouver les rythmes dans un autre contexte, au lieu de réciter une liste de lettres.'],
 ['l-morse-mots-durk','Retrouver des lettres dans un mot','ETIMANSODURK',['MARTIN','RADIO','TROIS'],'D, U, R et K étendent le vocabulaire. Quand deux caractères se ressemblent, réécoute le rythme entier puis retrouve leur place dans le mot.'],
 ['l-morse-mots-longs','Composer sans perdre les séparations','ETIMANSODURKGWBVFLPJ',['LOUIS','PARIS','VIVE'],'Ces mots emploient les caractères déjà rencontrés, dont les lettres plus longues. Un trait dans une autre position change le caractère ; le silence entre lettres reste tout aussi important.']
];
for(const [id,title,known,words,paragraph]of learnedGroups){
 const fallback=words[0];
 add(L(id,title,'Petits groupes, rappel et écoute',[S.morseWords,S.morseEncode,S.morseListen],[
  paragraph,
  'Cherche d’abord le mot entier à composer, puis avance caractère par caractère. Garde une pause entre les lettres et une pause plus longue entre deux mots. Tu peux ralentir les espaces pour te laisser le temps de reconnaître les caractères.',
  `Les mots d’exemple de ce cours sont ${words.join(', ')}. Les exercices n’utilisent que les caractères indiqués ici : ${known}. Un prénom du profil ou d’un ami peut remplacer un exemple lorsque tous ses caractères conviennent ; sinon un exemple adapté est conservé.`
 ],[...words.map(word=>E(`Compose le mot ${word} en Morse.`,word)),{...E(`Compose ${fallback} en Morse.`,fallback),template:{type:'morse-name',sourceText:'Compose {{name}} en Morse.',characters:known,fallback,mode:'encode'},skillIds:[S.morseEncode]}, {...T('Écoute ce groupe en Morse, puis écris ce que tu reconnais.',[fallback],'Retrouve chaque caractère du groupe en respectant les pauses.'),bands:[morse(fallback)],template:{type:'morse-name',sourceText:'Écoute ce groupe en Morse, puis écris ce que tu reconnais.',characters:known,fallback,mode:'text'},skillIds:[S.morseListen]}],{source:'morse',refs:['morse','morse-rhythm'],known,cert:0,explore:2}));
}
add(L('l-morse-chiffres-groupes','Des nombres dans le trafic','Garder les cinq éléments de chaque chiffre',[S.morseWords,S.morseListen],[
 'Les chiffres Morse ont cinq éléments. Distingue le zéro, fait de cinq traits, de la lettre O, faite de trois traits. Un report ou un indicatif doit conserver ces caractères sans les raccourcir.',
 'Pour reconnaître un groupe, garde les chiffres déjà entendus puis réécoute la partie incertaine. Une suite nouvelle empêche de retrouver la réponse seulement par habitude.',
 'Les exemples 73 et 599 ont un usage de trafic : 73 est une salutation, et 599 peut être un report RST. Le sens ne change pas les caractères à transmettre.'
],[E('Compose le groupe 73 en Morse.','73'),E('Compose le report 599 en Morse.','599'),T('Combien d’éléments contient chaque chiffre Morse ?','5','Chaque chiffre comporte cinq points ou traits.'),{...T('Écoute et saisis ce groupe de chiffres.',['73'],'Le groupe doit être transcrit dans le même ordre.'),bands:[morse('73')],template:{type:'morse-name',sourceText:'Écoute et saisis ce groupe.',characters:'0123456789',fallback:'73',mode:'text'}}],{source:'morse',refs:['morse','reports'],known:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',cert:0,explore:2}));
add(L('l-morse-vers-epellation','Du rythme à l’épellation','Relier l’oreille et l’alphabet international',[S.morseListen,S.nato],[
 'Reconnaître un groupe à l’oreille puis l’épeler avec l’alphabet international combine deux rappels. Commence par retrouver les caractères ; cherche ensuite le mot de chaque lettre.',
 'Pour un groupe d’entraînement F4MNO, l’épellation serait Foxtrot, quatre, Mike, November, Oscar. Les chiffres se prononcent distinctement et les lettres gardent leurs mots conventionnels.',
 'Le clavier reste disponible si tu ne veux pas parler. Le groupe de l’exercice change ; écouter de nouveau est possible. Cette activité entraîne la mémoire des codes, sans constituer une épreuve réglementaire de Morse.'
],[{...P('Écoute le groupe Morse, puis épelle-le avec l’alphabet international.',['Foxtrot quatre Mike November Oscar','Foxtrot 4 Mike November Oscar'],'Transforme le signal en caractères, puis chaque lettre en son mot conventionnel.'),bands:[morse('F4MNO')],template:{type:'morse-call',sourceText:'Écoute le groupe Morse, puis épelle-le avec l’alphabet international.',characters:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',fallback:'F4MNO',mode:'nato'}},P('Comment épellerais-tu les lettres CQ ?','Charlie Quebec','C donne Charlie et Q donne Quebec.'),T('Quel mot international représente R ?','Romeo','R s’épelle Romeo.'),C('Une erreur dans un caractère signifie-t-elle qu’il faut abandonner les autres caractères reconnus ?','Non',['Oui toujours','Oui avec un chiffre','Oui avant la fin de l’écoute'],'Conserve les éléments fiables et réécoute la partie incertaine.')],{source:'morse',refs:['morse','nato'],known:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',cert:0,explore:3}));
add(L('l-morse-qso-appel','Comprendre un appel CW','CQ, DE, indicatif et invitation',[S.morseQso],[
 'En télégraphie, CQ est un appel général. DE introduit l’identité de la station qui appelle. Un appel d’entraînement peut s’écrire CQ CQ DE F4MNO F4MNO K : appel général, de F4MNO, puis invitation à transmettre.',
 'Ces groupes ne sont pas une traduction mot à mot de toutes les phrases françaises. Pour demander si la fréquence est occupée, QRL ? est pertinent ; 73 est une salutation et ne signifie pas « est-ce qu’on me reçoit ? ».',
 'Les exemples sont simulés dans Hamigo. Sur l’air, le certificat, l’indicatif attribué, l’écoute préalable, les règles de bande et la courtoisie restent nécessaires.'
],[T('Quel groupe introduit l’indicatif de la station qui appelle ?','DE','DE indique « de » avant l’identité de l’appelant.'),T('Quel groupe sert à l’appel général ?','CQ','CQ s’adresse aux stations susceptibles de répondre.'),C('CQ CQ DE F4MNO K signifie ici…','Un appel général de F4MNO avec invitation à transmettre',['Une fin de contact de F4MNO','Une mesure de ROS','Une demande de chiffrement'],'CQ appelle, DE annonce l’identité et K invite à transmettre.'),C('Quelle formulation demande si la fréquence est occupée ?','QRL ?',['73','599','QRT'],'QRL ? porte sur l’occupation de la fréquence.'),E('Compose le groupe CQ DE en Morse.','CQ DE')],{source:'morse',refs:['morse','qcodes','abbreviations','operating-rules'],known:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789?/',cert:0,explore:3}));
add(L('l-morse-qso-comprendre','Suivre un échange bref','Indicatifs, report et fin de contact',[S.morseQso,S.morseListen],[
 'Un échange CW bref identifie les stations et peut transmettre un report RST, un prénom et une localisation. L’ordre et les abréviations varient ; la priorité reste de comprendre qui parle et quelle information est donnée.',
 'Exemple de contenu : F4MNO DE F6KGL UR RST 579. F6KGL s’adresse à F4MNO et lui donne un report de 579. Le premier nombre décrit la lisibilité, le deuxième la force et le troisième la tonalité.',
 'Pour terminer, un remerciement et 73 peuvent précéder l’identification et le signal de fin approprié. Ne transforme pas automatiquement toute salutation française en un code Q : les conventions doivent être apprises dans leur contexte.'
],[C('F4MNO DE F6KGL UR RST 579 : qui transmet ici ?','F6KGL',['F4MNO','La station 579','Aucune station identifiable'],'DE précède l’identité de la station qui appelle.'),N('Dans RST 579, quelle note décrit la force du signal ?',7,'/9','La deuxième note RST est la force S.',0),C('Dans cet échange, 73 sert de…','Salutation',['Demande de lisibilité','Fréquence en MHz','Identifiant de parc'],'73 est une salutation de trafic.'),{...T('Écoute ce groupe Morse puis transcris les caractères reconnus.',['F4MNO'],'Reconnais le groupe avant d’interpréter son rôle dans l’échange.'),bands:[morse('F4MNO')],template:{type:'morse-call',sourceText:'Écoute ce groupe Morse puis transcris les caractères reconnus.',characters:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',fallback:'F4MNO',mode:'text'}}],{source:'morse',refs:['morse','reports','qcodes'],known:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789?/',cert:0,explore:3}));
add(L('l-classes-amplification','Pourquoi choisir une classe ?','Linéarité, conduction et rendement',[SK('amplifier-classes','Comparer les classes d’amplification')],[
 'Une classe d’amplification décrit notamment la fraction de période pendant laquelle le composant conduit. En classe A, il conduit toute la période ; en classe B, chaque branche conduit idéalement une demi-période. AB se situe entre ces cas.',
 'La linéarité vise à conserver la forme du signal. Un signal à enveloppe variable, comme la BLU, demande une chaîne compatible avec cette variation. Le rendement est le rapport puissance utile sur puissance absorbée.',
 'La classe C conduit moins d’une demi-période et emploie un circuit accordé dans ses usages radio classiques. Son rendement ne signifie pas qu’elle conviendrait directement à amplifier sans déformation toute modulation d’amplitude.'
],[T('Quelle classe conduit pendant toute la période ?','A','La classe A conduit sur 360 degrés.'),N('Puissance utile 20 W, puissance absorbée 50 W. Rendement ?',40,'%','η = 20/50 × 100 = 40 %.'),C('Pourquoi la BLU demande-t-elle une amplification linéaire adaptée ?','Son enveloppe transporte l’information',['Sa puissance doit être nulle','Elle ne contient aucune variation','Elle interdit tout filtre'],'Déformer l’enveloppe déforme le message et crée des produits indésirables.'),C('La classe C conduit idéalement…','Moins d’une demi-période',['Toute la période','Exactement deux périodes','Sans alimentation'],'La durée de conduction est inférieure à 180 degrés.')],{source:'active',refs:['amplifiers-oscillators','modulations']}));
add(L('l-quartz-pll','Tenir une fréquence','Oscillateur, quartz et synthèse',[SK('frequency-stability','Comprendre une référence stable')],[
 'Un oscillateur entretenu compense les pertes et produit un signal périodique. Un réseau LC ou une résonance à quartz peut sélectionner la fréquence. La stabilité décrit sa capacité à rester proche de la valeur voulue.',
 'Un quartz est un résonateur piézoélectrique ; il ne fournit pas seul une puissance RF entretenue. La température et le circuit influencent encore la fréquence.',
 'Une boucle à verrouillage de phase, PLL, compare une phase ou fréquence à une référence et corrige un oscillateur commandé. Elle permet notamment de synthétiser des fréquences à partir d’une référence stable.'
],[T('Quel composant piézoélectrique fournit une résonance stable ?',['quartz'],'Le quartz apporte une référence de fréquence.'),C('Un quartz seul, sans circuit alimenté, produit-il une oscillation entretenue ?','Non',['Oui indéfiniment','Oui si le signal est numérique','Oui en changeant l’antenne'],'Le circuit actif apporte l’énergie qui compense les pertes.'),T('Quel sigle désigne une boucle à verrouillage de phase ?',['PLL'],'Une PLL asservit un oscillateur à une référence.'),C('La stabilité d’un oscillateur est-elle la même chose que sa puissance ?','Non',['Oui','Oui en FM','Oui avec un quartz'],'Fréquence et puissance sont des propriétés différentes.')],{source:'active',refs:['amplifiers-oscillators']}));
add(L('l-image-reception','Pourquoi reçoit-on une fréquence image ?','Le mélangeur donne plusieurs produits',[SK('image-frequency','Écarter une fréquence image')],[
 'Un mélangeur produit notamment la somme et la différence des fréquences d’entrée. Un récepteur superhétérodyne conserve un produit pour obtenir sa fréquence intermédiaire.',
 'Deux signaux situés de part et d’autre de l’oscillateur local peuvent donner la même différence. Avec un oscillateur à 10 MHz et une FI de 1 MHz, 9 MHz et 11 MHz peuvent tous deux conduire à 1 MHz.',
 'Un filtrage avant le mélangeur aide à rejeter le signal image. Un filtre seulement placé après ne peut pas toujours séparer deux signaux déjà tombés sur la même FI.'
],[N('Signal 9 MHz, oscillateur 10 MHz. Produit différence ?',1,'MHz','|10 − 9| = 1 MHz.'),N('Quel autre signal autour de 10 MHz donne une différence de 1 MHz ?',11,'MHz','11 − 10 = 1 MHz.'),C('Où faut-il aider à rejeter l’image avant qu’elle partage la FI ?','Avant le mélangeur',['Uniquement dans le haut-parleur','Dans le carnet','Dans la source de chauffage'],'Le filtre d’entrée distingue encore les fréquences RF.'),T('Quel nom porte la fréquence choisie après conversion ?',['fréquence intermédiaire','FI'],'Le superhétérodyne traite le signal sur une fréquence intermédiaire.')],{source:'radio',refs:['radio-blocks','filters']}));
add(L('l-bruit-largeur','Un signal dans le bruit','Largeur de réception et lisibilité',[SK('noise-bandwidth','Relier bruit et largeur de bande')],[
 'Un récepteur recueille le signal utile et du bruit. La puissance de bruit thermique augmente avec la température et la largeur de bande. Réduire la largeur peut donc réduire le bruit accepté.',
 'Un filtre trop étroit coupe aussi une partie du signal utile. Il faut conserver la largeur nécessaire au mode. Augmenter le volume amplifie généralement le signal et le bruit ensemble : cela ne crée pas le rapport signal sur bruit manquant.',
 'Le rapport signal sur bruit et la lisibilité ne sont pas identiques à une seule indication de force. Un signal fort mais brouillé peut être difficile à comprendre.'
],[C('À température identique, une plus grande largeur de réception admet généralement…','Plus de bruit thermique',['Aucun bruit','Toujours moins de bruit','Une fréquence nulle'],'La puissance de bruit est proportionnelle à la largeur de bande.'),C('Pourquoi ne pas rendre le filtre arbitrairement étroit ?','Il peut couper le signal utile',['Le bruit est obligatoire','Le gain micro serait nul','La pile changerait de chimie'],'Le mode demande une certaine largeur.'),C('Monter seulement le volume garantit-il un meilleur rapport signal sur bruit ?','Non',['Oui','Oui avec un haut-parleur neuf','Oui en BLU uniquement'],'Le signal et le bruit sont souvent amplifiés ensemble.'),T('Quel mot décrit la facilité à comprendre un message reçu ?',['lisibilité','lisibilite','intelligibilité'],'La lisibilité s’évalue par la compréhension.')],{source:'radio',refs:['emc-noise','radio-blocks']}));
add(L('l-synthese-calculs','Choisir avant de calculer','Grandeur, unité et contrôle du résultat',[SK('calculation-method','Choisir et vérifier un calcul')],[
 'Commence par dire ce que tu cherches et dans quelle unité. Puis repère les données et le montage. Le nom de la formule compte moins que la relation entre les grandeurs.',
 'Convertis les préfixes avant d’utiliser une relation si elle exige les unités de base. Écris les parenthèses sur la calculatrice. Après le calcul, vérifie l’ordre de grandeur et le sens de variation.',
 'Une résistance équivalente en parallèle ne dépasse pas la plus petite branche. Une perte passive ne crée pas de puissance. Une fréquence plus élevée correspond à une longueur d’onde plus courte dans un même milieu.'
],[C('Deux résistances positives sont en parallèle. Le résultat doit être…','Inférieur à la plus petite branche',['Supérieur à la somme','Toujours égal à la plus grande','Négatif'],'Les conductances s’ajoutent.'),C('Avant de calculer R avec un courant en mA, quelle étape est utile ?','Convertir les mA en A',['Multiplier arbitrairement la tension','Changer d’indicatif','Ignorer les unités'],'La relation R = U/I donne des ohms avec volts et ampères.'),T('Quel contrôle rapide vérifie si un résultat est plausible ?',['ordre de grandeur','estimation','sens de variation'],'Une estimation peut repérer une inversion ou un préfixe oublié.'),N('Une résistance de 1 kΩ sous 2 V reçoit quel courant ?',2,'mA','I = 2/1 000 = 0,002 A = 2 mA.')],{source:'math',refs:['formulas','math-basics']}));
const allNew=new Map(newly.map(l=>[l.id,l]));
const get=id=>oldLessons.get(id)||allNew.get(id)||(()=>{throw Error('Unknown lesson '+id)})();
// These activities only arrange the already displayed phonetic answers. Preserve history, replace recall.
const retired=oldLessons.get('c02-l01').questions.filter(q=>['match','order'].includes(q.kind));
oldLessons.get('c02-l01').questions=oldLessons.get('c02-l01').questions.filter(q=>!retired.includes(q));
